{
  "Amazon": {
    "detectors": [
      {
        "presentMatcher": [
          {
            "type": "css",
            "target": {
              "selector": "[id*='cos-banner']"
            }
          }
        ],
        "showingMatcher": [
          {
            "type": "css",
            "target": {
              "selector": "[id*='cos-banner']",
              "displayFilter": true
            }
          }
        ]
      }
    ],
    "methods": [
      {
        "name": "HIDE_CMP",
        "action": {
          "type": "hide",
          "target": {
            "selector": "[id*='cos-banner']"
          }
        }
      },
      {
        "name": "OPEN_OPTIONS",
        "action": {
          "type": "click",
          "target": {
            "selector": "#sp-cc-customize"
          }
        }
      },
      {
        "name": "DO_CONSENT",
        "action": {
          "type": "list",
          "actions": [
            {
              "type": "waitcss",
              "target": {
                "selector": "#saveSelectedPrefs"
              },
              "retries": 10,
              "waitTime": 500
            },
            {
              "type": "consent",
              "consents": [
                {
                  "type": "F",
                  "trueAction": {
                    "type": "list",
                    "actions": [
                      {
                        "type": "click",
                        "parent": {
                          "selector": ".customize-container",
                          "childFilter": {
                            "target": {
                              "selector": "input[data-persistence-model='APC_STORES_ADS_COOKIE_1P']"
                            }
                          }
                        },
                        "target": {
                          "selector": ".a-column.a-span6 button[value='on']"
                        }
